import { useEffect, useRef, useState } from "react";
import { forceCollide, forceSimulation, forceX, forceY } from "d3-force";
//#region src/hooks/useBeeswarmLayout.ts
/**
* d3-force calcule les positions, React rend. Les nœuds persistent d'un rendu à
* l'autre pour que les mises à jour s'animent au lieu de sauter.
*/
function useBeeswarmLayout(input, width) {
	const [nodes, setNodes] = useState([]);
	const cache = useRef(/* @__PURE__ */ new Map());
	useEffect(() => {
		if (!width || input.length === 0) {
			setNodes([]);
			return;
		}
		const next = input.map((d) => {
			const prev = cache.current.get(d.id);
			return {
				id: d.id,
				targetX: d.x,
				targetY: d.y,
				r: d.r,
				yMin: d.yMin ?? -Infinity,
				yMax: d.yMax ?? Infinity,
				x: prev?.x ?? Math.random() * width,
				y: prev?.y ?? d.y + (Math.random() - .5) * 120
			};
		});
		next.forEach((n) => cache.current.set(n.id, n));
		const sim = forceSimulation(next).force("x", forceX((d) => d.targetX).strength(.9)).force("y", forceY((d) => d.targetY).strength(.3)).force("collide", forceCollide((d) => d.r + 1.2).iterations(2)).alpha(1).alphaMin(.004).alphaDecay(.055).velocityDecay(.34).stop();
		let frame = 0;
		const step = () => {
			sim.tick();
			for (const n of next) {
				const lo = n.yMin + n.r;
				const hi = n.yMax - n.r;
				if (n.y < lo) {
					n.y = lo;
					n.vy = 0;
				} else if (n.y > hi) {
					n.y = hi;
					n.vy = 0;
				}
			}
			setNodes(next.map((n) => ({ ...n })));
			if (sim.alpha() > sim.alphaMin()) frame = requestAnimationFrame(step);
		};
		frame = requestAnimationFrame(step);
		return () => {
			cancelAnimationFrame(frame);
			sim.stop();
		};
	}, [input, width]);
	return nodes;
}
//#endregion
export { useBeeswarmLayout as t };
